        <tr ${m}><td ${z}>İptal Edilen Ürün Kaybı (${p.cancelledItemsCount||0} adet)</td><td ${z} style="text-align:right;font-weight:700;color:#f59e0b;">${b(p.cancelledItemsLoss||0)}</td></tr>
